  const all = [...a.platform, ...a.industries.flatMap((x) => x.items)];
  const fmt = (t) => `- ${t.text}${t.instead ? `\uFF08\u6362\u6210\uFF1A${t.instead}\uFF09` : ""}`;
  const dirs = all.filter((t) => t.kind === "direction");
  const says = all.filter((t) => t.kind !== "direction");
